// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { SegmentedControl } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Actions/SegmentedControl)

figma.connect(SegmentedControl, FIGMA_NODE_URL, {
  props: {
    size: figma.enum('size', { 'sm': 'sm', 'md': 'md', 'lg': 'lg' }),
    fullWidth: figma.boolean('fullWidth'),
    isDisabled: figma.boolean('isDisabled'),
  },
  example: ({ size, fullWidth, isDisabled }) => (
    <SegmentedControl size={size} fullWidth={fullWidth} isDisabled={isDisabled}></SegmentedControl>
  ),
});
